#' Baseline Characteristics (Table 1)
#'
#' Automated generation of publication-ready Baseline Characteristics table 
#' (Table 1) with distribution audit, adaptive reporting, and statistical 
#' testing.
#' @param data .
#' @param vars .
#' @param group .
#' @param showTotal .
#' @param method .
#' @param normAlpha .
#' @param varEqual .
#' @param catTest .
#' @param statFormatCont .
#' @param statFormatCat .
#' @param pctType .
#' @param missing .
#' @param showPval .
#' @param flag .
#' @param showTestName .
#' @param showStat .
#' @param padjust .
#' @param showSmd .
#' @param decMark .
#' @param digits .
#' @param pDigits .
#' @param showNormAudit .
#' @param showPostHoc .
#' @param postHocMethod .
#' @param showPlot .
#' @param plotTypeCont .
#' @param plotTypeCat .
#' @param plotType .
#' @param plotScope .
#' @param plotRemoveOutliers .
#' @param plotSignif .
#' @param plotVars .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$instructions} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$tab1} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$normAudit} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$postHocNotice} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$postHoc} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$plots} \tab \tab \tab \tab \tab an array of images \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$tab1$asDF}
#'
#' \code{as.data.frame(results$tab1)}
#'
#' @export
mTAB1 <- function(
    data,
    vars,
    group,
    showTotal = TRUE,
    method = "auto",
    normAlpha = 0.05,
    varEqual = "welch",
    catTest = "auto",
    statFormatCont = "mean_sd",
    statFormatCat = "n_pct",
    pctType = "col",
    missing = "ifany",
    showPval = TRUE,
    flag = FALSE,
    showTestName = TRUE,
    showStat = FALSE,
    padjust = "none",
    showSmd = FALSE,
    decMark = "auto",
    digits = -1,
    pDigits = -1,
    showNormAudit = FALSE,
    showPostHoc = FALSE,
    postHocMethod = "holm",
    showPlot = FALSE,
    plotTypeCont = "box_clean",
    plotTypeCat = "bar",
    plotType = "auto",
    plotScope = "all",
    plotRemoveOutliers = FALSE,
    plotSignif = FALSE,
    plotVars = list()) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("mTAB1 requires jmvcore to be installed (restart may be required)")

    if ( ! missing(vars)) vars <- jmvcore::resolveQuo(jmvcore::enquo(vars))
    if ( ! missing(group)) group <- jmvcore::resolveQuo(jmvcore::enquo(group))
    if ( ! missing(plotVars)) plotVars <- jmvcore::resolveQuo(jmvcore::enquo(plotVars))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(vars), vars, NULL),
            `if`( ! missing(group), group, NULL),
            `if`( ! missing(plotVars), plotVars, NULL))

    for (v in group) if (v %in% names(data)) data[[v]] <- as.factor(data[[v]])

    options <- mTAB1Options$new(
        vars = vars,
        group = group,
        showTotal = showTotal,
        method = method,
        normAlpha = normAlpha,
        varEqual = varEqual,
        catTest = catTest,
        statFormatCont = statFormatCont,
        statFormatCat = statFormatCat,
        pctType = pctType,
        missing = missing,
        showPval = showPval,
        flag = flag,
        showTestName = showTestName,
        showStat = showStat,
        padjust = padjust,
        showSmd = showSmd,
        decMark = decMark,
        digits = digits,
        pDigits = pDigits,
        showNormAudit = showNormAudit,
        showPostHoc = showPostHoc,
        postHocMethod = postHocMethod,
        showPlot = showPlot,
        plotTypeCont = plotTypeCont,
        plotTypeCat = plotTypeCat,
        plotType = plotType,
        plotScope = plotScope,
        plotRemoveOutliers = plotRemoveOutliers,
        plotSignif = plotSignif,
        plotVars = plotVars)

    analysis <- mTAB1Class$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

